codeExamples.code:
-- Add a NOT NULL after backfilling defaults
UPDATE orders SET status = 'PENDING' WHERE status IS NULL;
ALTER TABLE orders ALTER COLUMN status SET NOT NULL;

-- Add a CHECK without blocking writes (Postgres: validate later)
ALTER TABLE orders
    ADD CONSTRAINT chk_amount_positive CHECK (amount >= 0) NOT VALID;
ALTER TABLE orders VALIDATE CONSTRAINT chk_amount_positive;

-- Add a UNIQUE constraint backed by an index
ALTER TABLE customers ADD CONSTRAINT uq_email UNIQUE (email);
